window.WEEK_CONTENT_2_9 = {"2": {"learningIntention": "We can infer how setting and social dynamics (like seating at lunch) reveal character relationships.", "successCriteria": "I can explain why August finds lunchtime difficult and identify the message behind Mr. Browne's precepts.", "mon": {"mode": "teach", "label": "Monday", "icon": "📖", "modeLabel": "Teacher read", "range": "First-Day Jitters → Around the Room", "leadIn": ["Describe a time you walked into a room and felt like everyone was looking at you."], "comprehension": ["What does August notice first when he walks into the classroom?", "Why do you think the author includes so much detail about people's reactions/stares?"], "goAway": "Write about a rule you'd want a whole school to follow, and why.", "rubric": ["R1", "R3", "R8"], "rubricNote": "Listen for R1 (identifying what August notices and why) and R8 (reasoning about the author's choices)."}, "tue": {"mode": "group", "label": "Tuesday", "icon": "👥", "modeLabel": "Group read", "range": "Lamb to the Slaughter → Choose Kind", "leadIn": ["What do you think the saying “choose kind” means in your own words?"], "comprehension": ["What is Mr. Browne's “precept,” and why does he ask the class to write their own each month?", "Why might “Lamb to the Slaughter” be a scary chapter title for August's first day?"], "goAway": "Write your own class precept for this month — a short saying about how to treat others.", "rubric": ["R4", "R7", "R9"], "rubricNote": "R9 shows in the precept-writing task; R7 in how groups take turns reading and discussing."}, "wed": {"mode": "teach", "label": "Wednesday", "icon": "📖", "modeLabel": "Teacher read", "range": "Lunch → The Summer Table", "leadIn": ["Think about your own school's lunchroom. How do people usually choose where to sit?"], "comprehension": ["Why is choosing where to sit at lunch such a big deal for August?", "What does “The Summer Table” symbolise?"], "goAway": "Describe a time you sat somewhere new (a table, a bus seat, a mat spot) and how it felt.", "rubric": ["R1", "R2", "R8"], "rubricNote": "R2 shows well here — the Summer Table works as a symbol, so watch for students unpacking that layer of meaning."}, "thu": {"mode": "group", "label": "Thursday", "icon": "👥", "modeLabel": "Group read", "range": "One to Ten → Jack Will (the chapter)", "leadIn": ["On a scale of 1–10, how “bad” do you think a day can really get before it's actually okay again?"], "comprehension": ["Why does August rate his days on a scale of 1 to 10?", "What does his friendship with Jack Will seem to be turning into?"], "goAway": "Rate your best and worst school day ever (1–10) and explain why.", "rubric": ["R4", "R5", "R7"], "rubricNote": "The go-away rating task is a quick R5 checkpoint — look for students explaining their rating with detail."}, "fri": {"mode": "quiz", "label": "Friday", "icon": "📝", "modeLabel": "Quiz day", "rubric": ["R2", "R6", "R10"], "rubricNote": "Quiz results are your best R6 evidence this week. Precept-writing across the week is strong R10 evidence too."}}, "3": {"learningIntention": "We can compare how the same events look different depending on whose point of view we're reading from.", "successCriteria": "I can explain why the author switches narrators to Via, and identify at least one new fact we learn about August from her perspective.", "mon": {"mode": "teach", "label": "Monday", "icon": "📖", "modeLabel": "Teacher read", "range": "Wake Me Up when September Ends → Mr. Browne's October Precept", "leadIn": ["What's your favourite thing about Halloween, and why do you think people love dressing up?"], "comprehension": ["Why might Halloween be extra complicated for August compared to other kids?"], "goAway": "If you designed the “perfect” Halloween costume for yourself, what would it be and why?", "rubric": ["R1", "R3", "R8"], "rubricNote": "Watch for R8 as students reason through why Halloween is uniquely complicated for August."}, "tue": {"mode": "group", "label": "Tuesday", "icon": "👥", "modeLabel": "Group read", "range": "Apples → Halloween", "leadIn": ["Have you ever overheard something you weren't meant to hear? How did it make you feel?"], "comprehension": ["What does August overhear on Halloween, and how does it change how he feels about Jack Will?", "Why is this such a turning point in the story?"], "goAway": "Write about a time someone said something (kindly or unkindly) that you weren't meant to hear.", "rubric": ["R4", "R7", "R9"], "rubricNote": "This is a big emotional turning point — R7 shows in how sensitively groups discuss it together."}, "wed": {"mode": "teach", "label": "Wednesday", "icon": "📖", "modeLabel": "Teacher read", "range": "School Pictures → The Bleeding Scream", "leadIn": ["How do you think it feels to see your own photo when you're not happy with how you look?"], "comprehension": ["How does August cope after what happened on Halloween?", "What does “The Bleeding Scream” costume incident reveal about how people react to August when they don't realise he's nearby?"], "goAway": "Write a short message of encouragement you'd send August after this tough week.", "rubric": ["R1", "R2", "R8"], "rubricNote": "R2 — the costume/mistaken-identity device is a strong structure-and-language discussion point."}, "thu": {"mode": "group", "label": "Thursday", "icon": "👥", "modeLabel": "Group read", "range": "Names (end Part One) → A Tour of the Galaxy (start Part Two: Via)", "leadIn": ["Whose voice do you think we'll hear from next, now that Part One is over?", "Why might the author want to tell part of the story through someone else's eyes?"], "comprehension": ["What new information do we learn about August's family from Via's opening chapter?", "How does Via describe her relationship with her brother?"], "goAway": "Write 3 things you think Via might find hard about being August's older sister — things August might not even notice.", "rubric": ["R4", "R5", "R7"], "rubricNote": "The switch to Via's narration is a great R5 moment — listen for students writing convincingly from her point of view."}, "fri": {"mode": "quiz", "label": "Friday", "icon": "📝", "modeLabel": "Quiz day", "rubric": ["R2", "R6", "R10"], "rubricNote": "Quiz results give strong R2 evidence this week (comparing narrators) alongside the usual R6/R10 checkpoints."}}, "4": {"learningIntention": "We can identify cause and effect in a story, and explain how a character's actions affect others around them.", "successCriteria": "I can explain what “The Plague” refers to and why it affects how other kids treat August's friends.", "mon": {"mode": "teach", "label": "Monday", "icon": "📖", "modeLabel": "Teacher read", "range": "Before August → August Through the Peephole", "leadIn": ["Do you think it's possible to love someone and still sometimes feel frustrated by how much attention they get? Why?"], "comprehension": ["What do we learn about Via's feelings before August was born?", "How does the “peephole” image work as a metaphor for how Via sees her family?"], "goAway": "Write about someone in your life who takes up “a lot of space” in a good way, and how that makes you feel.", "rubric": ["R1", "R3", "R8"], "rubricNote": "The peephole metaphor is a rich R8/R2 discussion point even though it's tagged here under thinking."}, "tue": {"mode": "group", "label": "Tuesday", "icon": "👥", "modeLabel": "Group read", "range": "High School → After School", "leadIn": ["What are you most looking forward to (or nervous about) when you eventually go to high school/intermediate?"], "comprehension": ["How is Via's high school experience different from August's at Beecher?", "Why might Via choose to keep her old friendships from before secret in some ways?"], "goAway": "Write about a “fresh start” you'd like to have and what you'd do differently.", "rubric": ["R4", "R7", "R9"], "rubricNote": "R9 shows in students engaging with the “fresh start” task and sharing ideas with their group."}, "wed": {"mode": "teach", "label": "Wednesday", "icon": "📖", "modeLabel": "Teacher read", "range": "The Padawan Bites the Dust → Breakfast", "leadIn": ["What's a nickname you have (or would want) and what does it mean?"], "comprehension": ["Why is the “Padawan” nickname significant to August and Jack's friendship?", "What tension is building at the family breakfast table?"], "goAway": "Write about a nickname that means something special to you or a friend.", "rubric": ["R1", "R2", "R8"], "rubricNote": "Watch for R1 — students noticing how the nickname signals genuine friendship, not mockery."}, "thu": {"mode": "group", "label": "Thursday", "icon": "👥", "modeLabel": "Group read", "range": "Genetics 101 → Out with the Old (end Part Two) + Weird Kids (start Part Three: Summer)", "leadIn": ["We are about to meet a brand-new narrator called Summer. What do you predict her connection to August might be?"], "comprehension": ["What does Via learn in science class that connects to her own family?", "Why does Summer choose to sit with August — what does this tell us about her character?"], "goAway": "Write about a time you chose to sit/stand with someone who was on their own, or a time someone did that for you.", "rubric": ["R4", "R5", "R7"], "rubricNote": "A new narrator arrives this lesson — good R5 opportunity in the Summer-perspective go-away writing."}, "fri": {"mode": "quiz", "label": "Friday", "icon": "📝", "modeLabel": "Quiz day", "rubric": ["R2", "R6", "R10"], "rubricNote": "This week's quiz leans on R10 — 'The Plague' is a direct, powerful example for the Choose Kind values strand."}}, "5": {"learningIntention": "We can explore how guilt and regret motivate a character's choices.", "successCriteria": "I can explain why Jack feels guilty and describe what he does to try to make things right.", "mon": {"mode": "teach", "label": "Monday", "icon": "📖", "modeLabel": "Teacher read", "range": "The Call → Four Things", "leadIn": ["Have you ever done or said something you instantly regretted? What did you do next?"], "comprehension": ["Why does Jack's mum make him call August?", "What does Jack decide to do differently after Halloween?"], "goAway": "Write about a time you had to apologise for something. How did you feel before and after?", "rubric": ["R1", "R3", "R8"], "rubricNote": "R8 shows in students reasoning about guilt and motivation — Jack's a great case study."}, "tue": {"mode": "group", "label": "Tuesday", "icon": "👥", "modeLabel": "Group read", "range": "Ex-Friends → Fortune Favors the Bold", "leadIn": ["What would you do if your friends started treating your best friend badly — would you speak up?"], "comprehension": ["What happens between Jack and Julian's group now that Jack has changed sides?", "Why does Jack think “fortune favours the bold”?"], "goAway": "Write about a time you had to choose between fitting in and doing what you believed was right.", "rubric": ["R4", "R7", "R9"], "rubricNote": "This is a strong R9 week — the go-away prompt asks students to reflect on real choices they've made."}, "wed": {"mode": "teach", "label": "Wednesday", "icon": "📖", "modeLabel": "Teacher read", "range": "Private School → Detention", "leadIn": ["What do you think it takes real courage to stand up for someone, even if it costs you something?"], "comprehension": ["What happens between Jack and Julian that leads to detention?", "Why might Jack feel it was worth it?"], "goAway": "Write about a moment of real courage you've seen (in real life, a book, or a movie).", "rubric": ["R1", "R2", "R8"], "rubricNote": "Watch for R8 as students weigh up whether Jack's actions were “worth it.”"}, "thu": {"mode": "group", "label": "Thursday", "icon": "👥", "modeLabel": "Group read", "range": "Season's Greetings → The War", "leadIn": ["What does it feel like when a whole friend group takes sides against you?"], "comprehension": ["How does the “war” between groups of kids affect August and Jack at school?", "What role does social media/texting play in this part of the story?"], "goAway": "Write about the effect that unkind messages (online or on paper) can have, even if “it was just a joke.”", "rubric": ["R4", "R5", "R7"], "rubricNote": "Directly relevant to Health & PE / Hauora links — good R10 evidence surfaces here too."}, "fri": {"mode": "quiz", "label": "Friday", "icon": "📝", "modeLabel": "Quiz day", "rubric": ["R2", "R6", "R10"], "rubricNote": "Jack's arc this week gives rich evidence for R10 (choosing kind even when it costs you something)."}}, "6": {"learningIntention": "We can recognise how small choices (like who you sit with) can carry big social meaning.", "successCriteria": "I can explain the significance of “switching tables” and describe a new character's role in the story.", "mon": {"mode": "teach", "label": "Monday", "icon": "📖", "modeLabel": "Teacher read", "range": "Switching Tables → Why I Didn't Sit with August the (end Part Four)", "leadIn": ["Why do you think where someone sits at lunch can matter so much in a school?"], "comprehension": ["What does “switching tables” represent for Jack and August's friendship?", "Why might it take courage to do something so small?"], "goAway": "Write about a small action that actually made a big difference to someone.", "rubric": ["R1", "R3", "R8"], "rubricNote": "R8 — a great chance to discuss how small, symbolic actions can carry big social meaning."}, "tue": {"mode": "group", "label": "Tuesday", "icon": "👥", "modeLabel": "Group read", "range": "Olivia's Brother → Our Town", "leadIn": ["If you were about to meet your friend's sibling for the first time, what would you want to know about them beforehand?"], "comprehension": ["Who is Justin, and how is he connected to Via?", "What is “Our Town” and why does it matter to this part of the story?"], "goAway": "Write about someone you've met through a friend or family member who became important to you.", "rubric": ["R4", "R7", "R9"], "rubricNote": "A new narrator (Justin) arrives — R7 shows in how groups introduce and discuss his perspective."}, "wed": {"mode": "teach", "label": "Wednesday", "icon": "📖", "modeLabel": "Teacher read", "range": "Ladybug → The Bus Stop", "leadIn": ["What's something small and ordinary that has ended up being one of your happiest memories?"], "comprehension": ["What does the “Ladybug” moment reveal about Via and Justin's relationship?", "How does August's world intersect with Via's here?"], "goAway": "Describe a small, ordinary moment that turned into a happy memory for you.", "rubric": ["R1", "R2", "R8"], "rubricNote": "R2 — notice how the story weaves August's and Via's worlds together through small connecting scenes."}, "thu": {"mode": "group", "label": "Thursday", "icon": "👥", "modeLabel": "Group read", "range": "Rehearsal → The Universe (end Part Five)", "leadIn": ["Have you ever been part of a performance (school play, sports game, concert)? How did it feel leading up to it?"], "comprehension": ["What play is Via rehearsing for, and why might it matter that August will be watching?", "What does Justin come to understand about August by the end of this part?"], "goAway": "Write about a time you were nervous before a performance or big moment — what helped you get through it?", "rubric": ["R4", "R5", "R7"], "rubricNote": "Strong R5 opportunity — writing about a real memory of nerves before a big moment."}, "fri": {"mode": "quiz", "label": "Friday", "icon": "📝", "modeLabel": "Quiz day", "rubric": ["R2", "R6", "R10"], "rubricNote": "Multiple narrators are now in play — quiz question 19 is great R2/R8 evidence about why the author uses so many voices."}}, "7": {"learningIntention": "We can identify how family relationships change and deepen over the course of a story.", "successCriteria": "I can explain what Via's “secret” is and describe how August reacts to change within his family.", "mon": {"mode": "teach", "label": "Monday", "icon": "📖", "modeLabel": "Teacher read", "range": "North Pole → Lobot", "leadIn": ["What's a family tradition you have, and what would it feel like if it suddenly changed?"], "comprehension": ["What does “North Pole” refer to in the family's traditions?", "Why might August feel uneasy about things changing?"], "goAway": "Write about a family tradition that means a lot to you.", "rubric": ["R1", "R3", "R8"], "rubricNote": "R1 — listen for students identifying August's unease with change and backing it up with evidence."}, "tue": {"mode": "group", "label": "Tuesday", "icon": "👥", "modeLabel": "Group read", "range": "Hearing Brightly → My Cave", "leadIn": ["Do you have a “cave” — a place you go to feel calm or think? Describe it."], "comprehension": ["What does the “Hearing Brightly” incident reveal about August's confidence/friendships now?", "What does August's “cave” symbolise?"], "goAway": "Draw or describe your own personal “cave” — your calm space and why it matters to you.", "rubric": ["R4", "R7", "R9"], "rubricNote": "A gentle, personal go-away task — good R9 engagement, and R4 in how clearly students describe their own space."}, "wed": {"mode": "teach", "label": "Wednesday", "icon": "📖", "modeLabel": "Teacher read", "range": "Goodbye → Heaven", "leadIn": ["How do people usually cope with losing something or someone important to them (a pet, a person, a stage of life)?"], "comprehension": ["What loss does August experience in this section?", "How does he process his grief?"], "goAway": "Write a kind message to someone who has experienced a loss.", "rubric": ["R1", "R2", "R8"], "rubricNote": "A sensitive lesson (the loss of Daisy) — keep the tone gentle; R10/empathy evidence is strong here."}, "thu": {"mode": "group", "label": "Thursday", "icon": "👥", "modeLabel": "Group read", "range": "Understudy → The Ending (end Part Six)", "leadIn": ["Would you rather be the star of a show or the “understudy” who's ready just in case? Why?"], "comprehension": ["What role does August end up playing in Via's school play, and why does this matter so much?", "What does “The Ending” of Part Six suggest is coming next?"], "goAway": "Write about a time you stepped up when someone unexpectedly needed you.", "rubric": ["R4", "R5", "R7"], "rubricNote": "R8 shows in students predicting what “The Ending” might signal for the story ahead."}, "fri": {"mode": "quiz", "label": "Friday", "icon": "📝", "modeLabel": "Quiz day", "rubric": ["R2", "R6", "R10"], "rubricNote": "A big week for family and growth themes — use quiz question 17 (comparing August's confidence since Week 1) as whole-term R1/R8 evidence."}}, "8": {"learningIntention": "We can analyse why a character might tell a lie, and predict the consequences of that choice.", "successCriteria": "I can explain Miranda's “camp lie” and describe how the setting of the nature retreat builds tension.", "mon": {"mode": "teach", "label": "Monday", "icon": "📖", "modeLabel": "Teacher read", "range": "Camp Lies → What I Miss Most", "leadIn": ["Why do people sometimes tell small lies to seem more interesting or important?"], "comprehension": ["Who is Miranda, and what lie does she tell at camp?", "What does she say she misses most, and why is that surprising?"], "goAway": "Write about a time you (or someone you know) told a small lie and what happened afterwards.", "rubric": ["R1", "R3", "R8"], "rubricNote": "R8 — a rich chance to discuss why people lie and predict where it will lead."}, "tue": {"mode": "group", "label": "Tuesday", "icon": "👥", "modeLabel": "Group read", "range": "School → Extraordinary, but No One There to See", "leadIn": ["Have you ever felt like you did something great but nobody was there to notice?"], "comprehension": ["How has Miranda's friendship with Via changed?", "Why does the chapter title suggest something “extraordinary” went unnoticed?"], "goAway": "Write about a personal achievement that felt extraordinary to you, even if barely anyone saw it.", "rubric": ["R4", "R7", "R9"], "rubricNote": "A reflective, personal go-away task — good R4/R9 evidence in how students share their own “unnoticed” achievements."}, "wed": {"mode": "teach", "label": "Wednesday", "icon": "📖", "modeLabel": "Teacher read", "range": "The Performance → After the Show (end Part Seven)", "leadIn": ["What do you think it means to finally be honest with someone after keeping a secret for a long time?"], "comprehension": ["What happens during Via's performance?", "How does Miranda's arc conclude?"], "goAway": "Write about the value of being honest, even when it's hard.", "rubric": ["R1", "R2", "R8"], "rubricNote": "R10 evidence is strong here — honesty and reconnecting are directly tied to the Choose Kind theme."}, "thu": {"mode": "group", "label": "Thursday", "icon": "👥", "modeLabel": "Group read", "range": "The Fifth-Grade Nature Retreat → Packing (start Part Eight: August)", "leadIn": ["If you were going on a school camp for a week, what would you be most excited or nervous about?"], "comprehension": ["What is the Nature Retreat, and why is it a big deal for August?", "What does his packing list tell us about how he's feeling?"], "goAway": "Make a packing list for your ideal school camp, and explain your top 3 must-haves.", "rubric": ["R4", "R5", "R7"], "rubricNote": "August's own narration returns here — R5 shows in how students capture his voice and nerves in writing."}, "fri": {"mode": "quiz", "label": "Friday", "icon": "📝", "modeLabel": "Quiz day", "rubric": ["R2", "R6", "R10"], "rubricNote": "Miranda's arc gives a strong contrast for R8/R10 — compare her way of coping (lying) with Jack's (owning up) from Week 5."}}, "9": {"learningIntention": "We can identify the climax of a story and reflect on how a character has changed from the beginning to the end.", "successCriteria": "I can describe the crisis at the retreat and explain how the community responds; I can summarise the key message of the book's ending.", "mon": {"mode": "teach", "label": "Monday", "icon": "📖", "modeLabel": "Teacher read", "range": "Daybreak → The Woods Are Alive", "leadIn": ["What's the scariest or most exciting thing that could happen on a night camp-out in the woods?"], "comprehension": ["What tension is building as the kids settle in for the night at camp?", "Why might unfamiliar surroundings make everyone (not just August) feel uneasy?"], "goAway": "Write about a time you felt genuinely scared, and how you (or someone) helped calm things down.", "rubric": ["R1", "R3", "R8"], "rubricNote": "R8 shows in students noticing how the author builds tension before the climax."}, "tue": {"mode": "group", "label": "Tuesday", "icon": "👥", "modeLabel": "Group read", "range": "Alien → The Emperor's Guard", "leadIn": ["If your group of friends were suddenly in danger, what do you think you'd do?"], "comprehension": ["What frightening event happens to August and his friends in the woods?", "How do the other boys (including some who weren't his friends before) react?"], "goAway": "Write about a moment when someone unexpected stood up for you, or you stood up for someone else.", "rubric": ["R4", "R7", "R9"], "rubricNote": "The story's climax — strong R7/R10 evidence in how groups discuss loyalty and standing up for others."}, "wed": {"mode": "teach", "label": "Wednesday", "icon": "📖", "modeLabel": "Teacher read", "range": "Sleep → The Last Precept", "leadIn": ["How do you think a scary shared experience might change how a group of people see each other afterwards?"], "comprehension": ["How does the school community respond once everyone is safe?", "What is “The Last Precept,” and how does it sum up the whole book's message?"], "goAway": "Write your own “last precept” — the one big lesson you'd want people to remember from this book.", "rubric": ["R1", "R2", "R8"], "rubricNote": "A key thematic moment — excellent R10 checkpoint as students write their own “last precept.”"}, "thu": {"mode": "group", "label": "Thursday", "icon": "👥", "modeLabel": "Group read", "range": "The Drop-Off → The Walk Home (finish the book)", "leadIn": ["How do you think August's very first day of school (Week 1) compares to how his year is ending now?"], "comprehension": ["What happens at the Awards ceremony?", "Why is it meaningful that the whole community — not just August's family — celebrates him by the end?", "What does the final chapter, “The Walk Home,” suggest about how far August (and everyone around him) has come?"], "goAway": "Write a full reflection: What is the biggest lesson “Wonder” has taught you about kindness, courage, or seeing people for who they really are?", "rubric": ["R4", "R5", "R7"], "rubricNote": "The book finishes today — this final reflection is your best whole-unit R1–R10 evidence, especially R5 and R10."}, "fri": {"mode": "quiz", "label": "Friday", "icon": "📝", "modeLabel": "Quiz day", "rubric": ["R2", "R6", "R10"], "rubricNote": "This is the final book quiz — use it (and Q17, which asks students to compare their Week 1 understanding) to update the whole class's R1–R10 rubric before Week 10's final project."}}};

